const D = { density:.5, energy:.6, scale:1, speed:1, hue:150, spread:.5, wave:.5, y:.82, x:.5, style:'polar night', act:'curtain', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const W = width, H = height, u = Math.min(W, H), TAU = Math.PI * 2;
const clp = (v, a, b) => Math.max(a, Math.min(b, v));
const st = P.style, sd = (P.seed | 0);
const key = W + 'x' + H + '_' + sd;
const hsh = i => { const s = Math.sin(i * 127.1 + sd * 311.7) * 43758.5453; return s - Math.floor(s); };

// ---- cached night sky + stars (size + seed keyed) ----
if (!S.sky || S.skyKey !== key) {
  S.skyKey = key;
  if (S.sky && S.sky.remove) S.sky.remove();
  const g = createGraphics(W, H);
  g.colorMode(HSB, 360, 100, 100, 100); g.noStroke();
  const topH = 228, botH = 252, bands = 46;
  for (let i = 0; i < bands; i++) {
    const f = i / bands;
    const h = topH + (botH - topH) * f;
    const b = 4 + f * 9;
    g.fill(h, 58 - f * 20, b); g.rect(0, H * f - 1, W, H / bands + 2);
  }
  const ns = Math.floor(80 + (W * H) / 10000);
  for (let i = 0; i < ns; i++) {
    const sx = hsh(i * 2 + 1) * W, sy = hsh(i * 2 + 2) * H * 0.92;
    const mag = hsh(i * 3 + 5);
    g.fill(210, 18, 55 + mag * 45, 25 + mag * 65);
    g.circle(sx, sy, 0.4 + mag * 1.5);
  }
  S.sky = g;
}
image(S.sky, 0, 0, W, H);

const intn = (K.intensity != null ? K.intensity : 0.6);
const swell = (K.swell != null ? K.swell : 0);

// ---- subtle live star twinkle (keeps sky itself in motion) ----
noStroke(); blendMode(ADD);
for (let i = 0; i < 7; i++) {
  const sx = hsh(i * 7 + 3) * W, sy = hsh(i * 7 + 4) * H * 0.55;
  const a = Math.sin(K.t * (1.1 + i * 0.27) + i * 1.3) * 0.5 + 0.5;
  fill(200, 14, 100, a * 16);
  circle(sx, sy, 1.4 + a * 2.6);
}
blendMode(BLEND);

// ---- aurora curtains ----
const en = clp(P.energy, 0, 1);
const sc = clp(P.scale, 0.4, 2.4);
const nC = Math.round(3 + P.density * 8);          // 3..11 curtains
const R = 20;                                       // rows per curtain
const top = H * 0.02, bot = H * clp(P.y, 0.3, 0.98);
const span = bot - top;
const zt = K.t * (0.06 + P.speed * 0.05);           // continuous noise evolution
const drift = K.t * (5 + P.speed * 9);              // px/s horizontal slide (real-time motion floor)
const waveAmp = (0.03 + P.wave * 0.14) * W * sc;    // horizontal wave amplitude
const audioB = A.mid * 0.6 + A.treble * 0.4 + A.rms * 0.5;
const hueBase = P.hue;
const spread = 30 + P.spread * 170;                 // hue spread top -> bottom fringe

// act dramaturgy: steady curtain / substorm surges / overhead corona
let ampMul = 1, briMul = 1, driftMul = 1;
if (P.act === 'storm') {
  const su = Math.sin(K.section * 1.3 + K.t * 0.08) * 0.5 + 0.5;
  ampMul = 1 + su * 0.9; briMul = 0.7 + su * 1.0 + K.pulse * 0.3; driftMul = 1 + su * 1.3;
} else if (P.act === 'corona') {
  ampMul = 1.3; briMul = 1.12; driftMul = 0.45;
}
const bright = (0.5 + en * 0.7) * (0.55 + intn * 0.7) * briMul;
const useAdd = (st === 'polar night' || st === 'spectral' || st === 'thermal');

function bandColor(rr, hueOff, cB) {
  const prof = Math.pow(Math.sin(Math.PI * Math.min(1, rr * 1.04)), 0.7);
  const glow = bright * cB * (0.8 + audioB * 0.7 + swell * 0.3);
  let h, s, b, al;
  if (st === 'thermal') {
    const m = clp(prof * glow * 0.95, 0, 1);
    h = (250 - 235 * m + 360) % 360; s = 92 - m * 34; b = 38 + 62 * m; al = prof * glow * 34;
  } else if (st === 'ink') {
    h = 220; s = 5 + 9 * rr; b = 66 + 24 * prof; al = prof * glow * 52;
  } else if (st === 'spectral') {
    h = (hueBase + hueOff + rr * spread + K.t * 8) % 360; s = 95; b = 100; al = prof * glow * 32;
  } else {
    h = (hueBase + hueOff + rr * spread + K.t * 4) % 360; s = 66 + 18 * rr; b = 78 + 22 * prof; al = prof * glow * 34;
  }
  return [((h % 360) + 360) % 360, clp(s, 0, 100), clp(b, 0, 100), clp(al, 0, 90)];
}

if (useAdd) blendMode(ADD);
for (let c = 0; c < nC; c++) {
  const cseed = c * 17.3;
  let bx = (hsh(c * 4 + 11) * 1.2 - 0.1) * W
    + drift * driftMul * (0.6 + hsh(c * 4 + 12) * 0.8)
    + (P.x - 0.5) * W * 0.3;
  bx = ((bx % (W * 1.2)) + W * 1.2) % (W * 1.2) - W * 0.1;
  const hueOff = (hsh(c * 4 + 13) - 0.5) * spread * 0.6;
  const cB = 0.6 + hsh(c * 4 + 14) * 0.6;
  const baseHW = (0.02 + P.density * 0.02) * W * sc * (0.7 + hsh(c * 4 + 15) * 0.9);
  const lx = [], rx = [], ys = [];
  for (let r = 0; r <= R; r++) {
    const rr = r / R, y = top + span * rr;
    const nz = noise(rr * 2.2 + cseed, zt + cseed * 0.1);
    const nz2 = noise(rr * 5.0 + cseed * 1.7, zt * 1.4 + 30);
    const cx = bx + (nz - 0.5) * 2 * waveAmp * ampMul
      + Math.sin(rr * TAU * 1.5 + K.t * 0.5 + cseed) * waveAmp * 0.25;
    const hw = baseHW * (0.5 + nz2) * (0.6 + rr * 0.7);
    lx.push(cx - hw); rx.push(cx + hw); ys.push(y);
  }
  if (st === 'schematic') {
    const lh = (hueBase + hueOff + 120) % 360;
    noFill(); strokeWeight(1);
    stroke(lh, 55, 92, 72);
    beginShape(); for (let r = 0; r <= R; r++) vertex((lx[r] + rx[r]) * 0.5, ys[r]); endShape();
    stroke(lh, 42, 72, 46);
    beginShape(); for (let r = 0; r <= R; r++) vertex(lx[r], ys[r]); endShape();
    beginShape(); for (let r = 0; r <= R; r++) vertex(rx[r], ys[r]); endShape();
    stroke(lh, 30, 60, 30);
    for (let r = 0; r <= R; r += 3) line(lx[r], ys[r], rx[r], ys[r]);
    continue;
  }
  noStroke();
  for (let r = 0; r < R; r++) {
    const rr = (r + 0.5) / R, col = bandColor(rr, hueOff, cB);
    fill(col[0], col[1], col[2], col[3]);
    beginShape();
    vertex(lx[r], ys[r]); vertex(rx[r], ys[r]);
    vertex(rx[r + 1], ys[r + 1]); vertex(lx[r + 1], ys[r + 1]);
    endShape(CLOSE);
  }
  // bright vertical shimmer strands (add live striation via K.t)
  if (useAdd) {
    noFill(); strokeWeight(1.1 + en * 1.3);
    const strands = 3 + Math.round(P.density * 4);
    for (let sI = 0; sI < strands; sI++) {
      const f = (sI + 0.5) / strands;
      const shim = 0.5 + 0.5 * Math.sin(K.t * (1.4 + sI * 0.6) + c * 2 + f * 6);
      const col = bandColor(0.55, hueOff, cB);
      stroke(col[0], col[1] * 0.8, 100, 16 * shim * (0.6 + en));
      beginShape();
      for (let r = 0; r <= R; r += 2) vertex(lx[r] + (rx[r] - lx[r]) * f, ys[r]);
      endShape();
    }
  }
}
blendMode(BLEND);
drawingContext.shadowBlur = 0;
